/**
 * @file demo.c
 * @brief qdsp demonstration: band-pass filter + envelope + Goertzel tone detect.
 *
 * Build (desktop):
 *     cc -O2 -o demo examples/demo.c
 * Build (Cortex-M, no FPU):
 *     arm-none-eabi-gcc -O2 -mcpu=cortex-m4 -mfloat-abi=soft -o demo examples/demo.c
 */
#include <stdio.h>
#include <math.h>
#include "qdsp.h"

#define FS       48000
#define BLOCK_SIZE 480
#define Q15F(x)  ((q15_t)((x) * 32767.0))

/* Band-pass around 1000 Hz (generated by tools/gen_biquad.py --type bandpass --f0 1000 --fs 48000 --q 0.707). */
static qdsp_biquad_t bp = {
    .b0 = 2769, .b1 = 0, .b2 = -2769, .a1 = -32768, .a2 = 27229,
    .w1 = 0, .w2 = 0,
};

/* Goertzel detector for 1000 Hz in a block of 480 samples (tools/gen_goertzel.py --freq 1000 --fs 48000 --n 480). */
static qdsp_goertzel_t gz = {
    .coeff = 64973, .s_prev = 0, .s_prev2 = 0, .n = 0, .N = BLOCK_SIZE,
};

static qdsp_envelope_t env = { .attack = 5000, .release = 500, .env = 0 };

int main(void) {
    int detected = 0;
    q15_t env_peak = 0;
    for (int i = 0; i < BLOCK_SIZE; i++) {
        /* sum of two tones: 1000 Hz (target) + 5000 Hz (reject) */
        double t = (double)i / FS;
        double x = 0.5 * sin(2 * M_PI * 1000.0 * t)
                 + 0.5 * sin(2 * M_PI * 5000.0 * t);
        if (x >  1.0) x =  1.0;
        if (x < -1.0) x = -1.0;
        q15_t s = Q15F(x);

        q15_t y = qdsp_biquad_process(&bp, s);
        env_peak = qdsp_peak_update(env_peak, y);
        qdsp_envelope_process(&env, y);
        qdsp_goertzel_process(&gz, y);
    }
    q15_t power = qdsp_goertzel_power(&gz);
    detected = (power > (Q15_ONE / 4));   /* threshold = 0.25 */

    printf("Goertzel power (Q15) = %d  (threshold %d)\n", power, Q15_ONE / 4);
    printf("Envelope peak        = %d\n", env_peak);
    printf("Tone 1000 Hz %s\n", detected ? "DETECTED" : "not detected");
    return detected ? 0 : 1;
}
